import { CommonModule } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import {
    MAT_DIALOG_DATA,
    MatDialogModule,
    MatDialogRef,
} from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
import { i18n, notifyError } from '@placeos/common';
import {
    AnnounceDirective,
    DIALOG_TITLE_STYLES,
    IconComponent,
    TranslatePipe,
} from '@placeos/components';
import {
    type Playlist,
    type PlaylistApprover,
    type PlaylistItem,
    type PlaylistRevision,
} from '@placeos/ts-client';
import { MediaPreviewService } from '../media/media-preview.service';
import { SignagePlaylistService } from '../playlists/signage-playlist.service';
import { SignageContextService } from '../signage-context.service';
import { playlistMediaItems } from '../signage-playlist.util';
import { PlaylistApprovalPreviewComponent } from './playlist-approval-preview.component';
import { loadPlaylistApprovalVersions } from './playlist-approval.util';

export interface PlaylistRequestApprovalModalData {
    playlist: Playlist;
    approvers: PlaylistApprover[];
    selected_approver_id?: string;
}

export interface PlaylistRequestApprovalModalResult {
    approver_id: string;
    message: string;
}

@Component({
    selector: 'playlist-request-approval-modal',
    template: `
        <header
            class="bg-base-200 sticky top-0 z-10 m-2 w-[calc(100%-1rem)] rounded-sm border-none p-2"
        >
            <h2 mat-dialog-title class="px-2 text-xl font-medium">
                {{ 'SIGNAGE_MANAGER.REQUEST_APPROVAL' | translate }}
            </h2>
            @if (!loading()) {
                <button
                    icon
                    type="button"
                    matRipple
                    mat-dialog-close
                    [attr.aria-label]="
                        'SIGNAGE_MANAGER.CLOSE_REQUEST_APPROVAL' | translate
                    "
                >
                    <icon>close</icon>
                </button>
            }
        </header>
        @if (!loading()) {
            <div
                class="flex max-h-[70vh] max-w-[calc(100vw-2rem)] flex-col gap-4 overflow-auto px-4 pt-2 pb-4 max-md:w-auto max-md:flex-1"
                [ngClass]="show_preview() ? 'w-[50rem]' : 'w-[28rem]'"
            >
                @if (!show_preview()) {
                    <div>
                        <div class="text-base-content/70 text-sm">
                            {{ 'SIGNAGE_MANAGER.PLAYLIST_LABEL' | translate }}
                        </div>
                        <div class="font-medium">{{ data.playlist.name }}</div>
                    </div>
                    <div>
                        <label
                            id="approval-approver-label"
                            for="approval-approver"
                            >{{ 'SIGNAGE_MANAGER.APPROVER' | translate }}</label
                        >
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript w-full"
                        >
                            <mat-select
                                id="approval-approver"
                                aria-labelledby="approval-approver-label"
                                name="approval-approver"
                                [(ngModel)]="selected_approver_id"
                            >
                                <mat-option value="">{{
                                    'SIGNAGE_MANAGER.ANYONE' | translate
                                }}</mat-option>
                                @for (item of data.approvers; track item.id) {
                                    <mat-option [value]="item.id">
                                        {{ item.name || item.id }}
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                    </div>
                    <div>
                        <label for="message">{{
                            'SIGNAGE_MANAGER.MESSAGE' | translate
                        }}</label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript w-full"
                        >
                            <textarea
                                matInput
                                id="message"
                                name="message"
                                class="min-h-28 resize-y"
                                [placeholder]="
                                    'SIGNAGE_MANAGER.APPROVERS_NOTE_PLACEHOLDER'
                                        | translate
                                "
                                [(ngModel)]="message"
                            ></textarea>
                        </mat-form-field>
                    </div>
                }
                <button
                    type="button"
                    matRipple
                    class="border-base-300 bg-base-100 flex w-full items-center justify-between rounded-sm border p-2 text-left"
                    [class.bg-base-200]="show_preview()"
                    [attr.aria-pressed]="show_preview()"
                    (click)="togglePreview()"
                >
                    <div>
                        <div class="font-medium">
                            {{ 'SIGNAGE_MANAGER.PREVIEW_CHANGES' | translate }}
                        </div>
                        <div class="text-base-content/70 text-sm">
                            {{
                                'SIGNAGE_MANAGER.PREVIEW_CHANGES_HINT'
                                    | translate
                            }}
                        </div>
                    </div>
                    <icon class="px-2 text-2xl">{{
                        show_preview() ? 'visibility_off' : 'visibility'
                    }}</icon>
                </button>
                @if (show_preview()) {
                    @if (versions_error()) {
                        <div
                            class="text-base-content/70 flex flex-col items-center justify-center space-y-2 p-8"
                            role="alert"
                        >
                            <icon class="text-error text-4xl">error</icon>
                            <p class="text-sm">
                                {{
                                    'SIGNAGE_MANAGER.PLAYLIST_VERSIONS_LOAD_ERROR'
                                        | translate
                                }}
                            </p>
                        </div>
                    } @else {
                        <playlist-approval-preview
                            [versions]="playlist_versions()"
                            [media]="playlist_media()"
                            (preview)="previewItem($event)"
                        />
                    }
                }
            </div>
            <footer
                class="border-base-300 bg-base-100 sticky bottom-0 flex justify-end gap-2 border-t p-4"
            >
                @if (!show_preview()) {
                    <button
                        btn
                        type="button"
                        matRipple
                        class="inverse w-36"
                        mat-dialog-close
                    >
                        {{ 'COMMON.CANCEL' | translate }}
                    </button>
                }
                @if (show_preview() && can_update() && !versions_error()) {
                    <button
                        btn
                        type="button"
                        matRipple
                        class="inverse w-40"
                        [disabled]="!has_previous_version()"
                        (click)="undoChanges()"
                    >
                        {{ 'SIGNAGE_MANAGER.UNDO_CHANGES' | translate }}
                    </button>
                }
                @if (!show_preview()) {
                    <button
                        btn
                        type="button"
                        matRipple
                        class="w-44"
                        (click)="submit()"
                    >
                        {{ 'SIGNAGE_MANAGER.REQUEST_APPROVAL' | translate }}
                    </button>
                }
            </footer>
        } @else {
            <div>
                <div
                    class="flex flex-col items-center justify-center space-y-4 px-32 py-16"
                >
                    <mat-spinner diameter="32" aria-hidden="true" />
                    <p announce>{{ loading() }}</p>
                </div>
            </div>
        }
    `,
    styles: [DIALOG_TITLE_STYLES],
    imports: [
        AnnounceDirective,
        CommonModule,
        FormsModule,
        MatRippleModule,
        MatDialogModule,
        MatFormFieldModule,
        MatInputModule,
        MatProgressSpinnerModule,
        MatSelectModule,
        IconComponent,
        PlaylistApprovalPreviewComponent,
        TranslatePipe,
    ],
})
export class PlaylistRequestApprovalModalComponent {
    private readonly _context = inject(SignageContextService);
    private readonly _media_preview = inject(MediaPreviewService);
    private readonly _playlist_service = inject(SignagePlaylistService);
    public readonly data =
        inject<PlaylistRequestApprovalModalData>(MAT_DIALOG_DATA);
    private readonly _dialog_ref =
        inject<
            MatDialogRef<
                PlaylistRequestApprovalModalComponent,
                PlaylistRequestApprovalModalResult
            >
        >(MatDialogRef);

    public readonly selected_approver_id = signal(
        this.data.selected_approver_id || '',
    );
    public readonly message = signal('');
    public readonly show_preview = signal(false);
    public readonly loading = signal('');
    public readonly has_previous_version = signal(false);
    /** Whether the versions failed to load. Opening the preview again retries. */
    public readonly versions_error = signal(false);
    public readonly can_update = this._context.can_update;

    /** The latest version and the last approved version, newest first */
    public readonly playlist_versions = signal<PlaylistRevision[]>([]);
    public readonly playlist_media = () =>
        this.playlist_versions().map((playlist) =>
            playlistMediaItems(playlist),
        );

    public togglePreview() {
        const show_preview = !this.show_preview();
        this.show_preview.set(show_preview);
        if (show_preview) void this._loadPlaylistVersions();
    }

    private async _loadPlaylistVersions() {
        if (this.playlist_versions().length) return this.playlist_versions();
        const playlist_id = this.data?.playlist?.id || '';
        if (!playlist_id) return [];
        this.loading.set(i18n('SIGNAGE_MANAGER.LOADING_VERSIONS'));
        this.versions_error.set(false);
        try {
            const versions = await loadPlaylistApprovalVersions(playlist_id);
            this.playlist_versions.set(versions);
            this.has_previous_version.set(versions.length > 1);
            return versions;
        } catch {
            this.versions_error.set(true);
            notifyError(i18n('SIGNAGE_MANAGER.PLAYLIST_VERSIONS_LOAD_ERROR'));
            return [];
        } finally {
            this.loading.set('');
        }
    }

    public submit() {
        this._dialog_ref.close({
            approver_id: this.selected_approver_id(),
            message: this.message().trim(),
        });
    }

    /** Restore the last approved version. The service asks the user to confirm. */
    public async undoChanges() {
        const [, previous_version] = await this._loadPlaylistVersions();
        if (!previous_version) return;
        const undone = await this._playlist_service.undoPlaylistChanges(
            this.data.playlist,
            previous_version,
        );
        if (undone) this._dialog_ref.close();
    }

    public previewItem(item: PlaylistItem) {
        this._media_preview.previewMedia(item);
    }
}
